import itertools

def solve_small(n):
    # We want to find the minimum k such that there exists a set S of k cells
    # such that every 2x2 square has at least one horizontal or vertical edge
    # with both endpoints in S.
    # A 2x2 square at (i,j) has edges:
    # h(i,j), h(i+1,j), v(i,j), v(i,j+1)
    # where h(i,j) = {(i,j), (i,j+1)} and v(i,j) = {(i,j), (i+1,j)}

    # Let's represent each cell as a bit in a bitmask.
    # Total cells = n*n.
    num_cells = n * n
    squares = []
    for i in range(n - 1):
        for j in range(n - 1):
            # Square at (i,j) contains cells (i,j), (i,j+1), (i+1,j), (i+1,j+1)
            # These are indices: i*n+j, i*n+j+1, (i+1)*n+j, (i+1)*n+j+1
            squares.append([i*n+j, i*n+j+1, (i+1)*n+j, (i+1)*n+j+1])

    min_k = num_cells
    for k in range(1, num_cells + 1):
        for S in itertools.combinations(range(num_cells), k):
            S_set = set(S)
            all_squares_covered = True
            for sq in squares:
                # Check if any edge in the square is in E_S
                # Edges in square:
                # (sq[0], sq[1]), (sq[2], sq[3]), (sq[0], sq[2]), (sq[1], sq[3])
                edges = [(sq[0], sq[1]), (sq[2], sq[3]), (sq[0], sq[2]), (sq[1], sq[3])]
                covered = False
                for u, v in edges:
                    if u in S_set and v in S_set:
                        covered = True
                        break
                if not covered:
                    all_squares_covered = False
                    break
            if all_squares_covered:
                return k
    return min_k

for n in [2, 3, 4]:
    print(f"n={n}, k={solve_small(n)}")

